-- =====================================================
-- DỮ LIỆU MẪU (SEED DATA) CHO SMARTJOB POSTGRESQL
-- BTL/BTVN: TH3 - SmartJob AI & BI
-- Chạy script này trong pgAdmin hoặc psql:
-- psql -U smartjob_user -d smartjob_db -f docs/seed-data.sql
-- =====================================================

-- 1. ĐẢM BẢO KỸ NĂNG LINUX TỒN TẠI

-- 2. BẢNG USERS (Tài khoản công ty và ứng viên - Mật khẩu mặc định: 123456)
SELECT setval('users_user_id_seq', (SELECT MAX(user_id) FROM Users));

-- 3. BẢNG COMPANIES (Thông tin doanh nghiệp tuyển dụng)
SELECT setval('companies_company_id_seq', (SELECT MAX(company_id) FROM Companies));

-- 4. BẢNG JOBS (Tin tuyển dụng mẫu)
SELECT setval('jobs_job_id_seq', (SELECT MAX(job_id) FROM Jobs));

-- 5. BẢNG JOB_SKILLS (Yêu cầu kỹ năng cho từng công việc)
SELECT setval('job_skills_job_skill_id_seq', (SELECT MAX(job_skill_id) FROM Job_Skills));

-- 6. BẢNG CANDIDATES (Hồ sơ ứng viên)
SELECT setval('candidates_candidate_id_seq', (SELECT MAX(candidate_id) FROM Candidates));

-- 7. BẢNG CANDIDATE_SKILLS (Kỹ năng của ứng viên)
SELECT setval('candidate_skills_candidate_skill_id_seq', (SELECT MAX(candidate_skill_id) FROM Candidate_Skills));

-- 8. BẢNG EDUCATION (Học vấn ứng viên)
SELECT setval('education_education_id_seq', (SELECT MAX(education_id) FROM Education));

-- 9. BẢNG EXPERIENCE (Kinh nghiệm làm việc)
SELECT setval('experience_experience_id_seq', (SELECT MAX(experience_id) FROM Experience));

-- 10. BẢNG APPLICATIONS (Đơn ứng tuyển mẫu)
SELECT setval('applications_application_id_seq', (SELECT MAX(application_id) FROM Applications));

-- 11. BẢNG AI_MATCH_RESULTS (Kết quả AI Matching mẫu)
SELECT setval('ai_match_results_match_id_seq', (SELECT MAX(match_id) FROM AI_Match_Results));

-- 12. BẢNG JOB_VIEWS (Lượt xem mẫu cho BI Analytics)
SELECT setval('job_views_view_id_seq', (SELECT MAX(view_id) FROM Job_Views));
