INSERT INTO Jobs (job_id, company_id, job_title, job_description, requirements, benefits, position_level, employment_type, salary_min, salary_max, location, years_of_experience_required, status, view_count) VALUES (1, 1, 'Senior Python / Django Backend Developer', 'Phát triển hệ thống microservices và REST API phục vụ hàng triệu người dùng toàn cầu.', 'Ít nhất 3 năm kinh nghiệm với Python, Django/FastAPI, cơ sở dữ liệu PostgreSQL.', 'Lương tháng 13, thưởng dự án, bảo hiểm sức khỏe quốc tế, trợ cấp học chứng chỉ AWS.', 'Senior', 'full-time', 25000000.00, 45000000.00, 'Hà Nội', 3, 'active', 36) ON CONFLICT DO NOTHING;
INSERT INTO Jobs (job_id, company_id, job_title, job_description, requirements, benefits, position_level, employment_type, salary_min, salary_max, location, years_of_experience_required, status, view_count) VALUES (2, 2, 'AI / Machine Learning Engineer', 'Nghiên cứu và triển khai mô hình gợi ý (Recommendation System) và xử lý ngôn ngữ tự nhiên NLP.', 'Có kiến thức vững về Machine Learning, Deep Learning, kinh nghiệm với PyTorch/TensorFlow.', 'Môi trường trẻ trung, văn phòng chuẩn Silicon Valley, thưởng hiệu suất hàng quý.', 'Middle', 'full-time', 22000000.00, 38000000.00, 'TP. Hồ Chí Minh', 2, 'active', 26) ON CONFLICT DO NOTHING;
INSERT INTO Jobs (job_id, company_id, job_title, job_description, requirements, benefits, position_level, employment_type, salary_min, salary_max, location, years_of_experience_required, status, view_count) VALUES (3, 3, 'Frontend Developer (React & TypeScript)', 'Xây dựng giao diện Dashboard và hệ thống quản trị dữ liệu lớn cho các doanh nghiệp chuyển đổi số.', 'Thành thạo React, TypeScript, HTML/CSS, REST API. Tối ưu trải nghiệm UI/UX tốt.', 'Lương cạnh tranh, lộ trình thăng tiến rõ ràng, chế độ đãi ngộ hàng đầu ngành viễn thông.', 'Junior / Middle', 'full-time', 15000000.00, 28000000.00, 'Hà Nội', 1, 'active', 26) ON CONFLICT DO NOTHING;
INSERT INTO Jobs (job_id, company_id, job_title, job_description, requirements, benefits, position_level, employment_type, salary_min, salary_max, location, years_of_experience_required, status, view_count) VALUES (4, 1, 'DevOps Cloud Engineer (AWS / Kubernetes)', 'Thiết lập pipeline CI/CD, tự động hóa hạ tầng đám mây trên AWS và cụm Kubernetes.', 'Có kinh nghiệm triển khai Docker, Kubernetes, CI/CD và hạ tầng đám mây.', 'Thưởng theo dự án nước ngoài, cơ hội onsite Nhật Bản, Mỹ.', 'Senior', 'full-time', 30000000.00, 55000000.00, 'Đà Nẵng', 4, 'active', 25) ON CONFLICT DO NOTHING;
